121→/** Exit status and stderr, read out of a shell tool result envelope. */
122→export function outcomeOf(resultText) {
123→  const s = String(resultText ?? "");
124→  const code = /(?:^|\n)Exit code:\s*(\d+)/.exec(s);
125→  const stderr = /(?:^|\n)Stderr:\s*([\s\S]*)$/.exec(s);
126→  return {
127→    exit_code: code ? Number(code[1]) : null,
128→    stderr: stderr ? stderr[1].trim().slice(0, 400) : "",
129→  };
130→}
